    (1, 1): 5, (1, 2): 4, (1, 3): 3,
    (2, 1): 6, (2, 2): 5, (2, 3): 4,
    (3, 1): 7, (3, 2): 6, (3, 3): 5,
}
jobs = [1, 2, 3]
machines = [1, 2, 3]

# big M (larger than any possible makespan)
M = sum(t[j, m] for j in jobs for m in machines) + 10

prob = pulp.LpProblem("FlowShop", pulp.LpMinimize)

# start time of job i on machine m
S = pulp.LpVariable.dicts("S", [(i, m) for i in jobs for m in machines], lowBound=0, cat='Continuous')

# binary variable: y[i,j]=1 if job i precedes job j (same order on all machines)
y = pulp.LpVariable.dicts("y", [(i, j) for i in jobs for j in jobs if i != j], cat='Binary')

# each pair has a definite order
for i in jobs:
    for j in jobs:
        if i < j:
            prob += y[i, j] + y[j, i] == 1

# precedence on each machine according to the same order
for i in jobs:
    for j in jobs:
        if i != j:
            for m in machines:
                prob += S[j, m] >= S[i, m] + t[i, m] - M * (1 - y[i, j])

# machine capacity: a machine processes at most one job at a time
# enforce that if i precedes j then j cannot start before i finishes on that machine (already covered)
# also enforce that if j precedes i then i cannot start before j finishes
for i in jobs:
    for j in jobs:
        if i != j:
            for m in machines:
                prob += S[i, m] >= S[j, m] + t[j, m] - M * (1 - y[j, i])

# flow shop: job must finish on machine m before starting on m+1
for i in jobs:
    for m in machines[:-1]:
        prob += S[i, m+1] >= S[i, m] + t[i, m]

# makespan variable
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')
for i in jobs:
    prob += Cmax >= S[i, machines[-1]] + t[i, machines[-1]]

# objective
prob += Cmax

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
