import pulp

# Sets
products = ['A1', 'A2', 'A3']
months = ['Jan', 'Feb', 'Mar', 'Apr']

# Data
price = {'A1':124, 'A2':109, 'A3':115}
prod_cost = {'A1':73.30, 'A2':52.90, 'A3':65.40}
act_cost = {'A1':150000, 'A2':150000, 'A3':100000}
quota = {'A1':500, 'A2':450, 'A3':550}
min_batch = {'A1':20, 'A2':20, 'A3':16}
demand = {
    ('A1','Jan'):5300, ('A1','Feb'):1200, ('A1','Mar'):7400, ('A1','Apr'):5300,
    ('A2','Jan'):4500, ('A2','Feb'):5400, ('A2','Mar'):6500, ('A2','Apr'):7200,
    ('A3','Jan'):4400, ('A3','Feb'):6700, ('A3','Mar'):12500, ('A3','Apr'):13200
}
storage_cost = {'A1':3.50, 'A2':4.00, 'A3':3.00}
storage_cap = 800

# Model
prob = pulp.LpProblem('ProductionPlanning', pulp.LpMaximize)

# Decision variables
produce = pulp.LpVariable.dicts('Prod', (products, months), lowBound=0, cat='Continuous')
activate = pulp.LpVariable.dicts('Act', (products, months), cat='Binary')
inventory = pulp.LpVariable.dicts('Inv', (products, months), lowBound=0, cat='Continuous')

# Objective: revenue - production cost - activation cost - storage cost
revenue = sum(price[p]*demand[(p,m)] for p in products for m in months)
prod_cost_term = sum(prod_cost[p]*produce[p][m] for p in products for m in months)
act_cost_term = sum(act_cost[p]*activate[p][m] for p in products for m in months)
store_cost_term = sum(storage_cost[p]*inventory[p][m] for p in products for m in months)

prob += revenue - prod_cost_term - act_cost_term - store_cost_term

# Constraints
# Production limits and minimum batch
for p in products:
    for m in months:
        prob += produce[p][m] <= quota[p]*activate[p][m]
        prob += produce[p][m] >= min_batch[p]*activate[p][m]

# Inventory balance
for p in products:
    for idx,m in enumerate(months):
        if idx==0:
            prev_inv = 0
        else:
            prev_inv = inventory[p][months[idx-1]]
        prob += inventory[p][m] == prev_inv + produce[p][m] - demand[(p,m)]

# Storage capacity each month
for m in months:
    prob += sum(inventory[p][m] for p in products) <= storage_cap

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")

