# Sets
products = ['I', 'II', 'III']
A_machines = ['A1', 'A2']
B_machines = ['B1', 'B2', 'B3']

# Processing times (hours per unit)
# A step times
time_A = {
    ('I','A1'):5, ('I','A2'):7,
    ('II','A1'):10, ('II','A2'):9,
    ('III','A1'):0, ('III','A2'):12,   # III cannot use A1
}
# B step times
time_B = {
    ('I','B1'):6, ('I','B2'):4, ('I','B3'):7,
    ('II','B1'):0, ('II','B2'):8, ('II','B3'):0,   # II only on B2 (time assumed 8)
    ('III','B1'):0, ('III','B2'):11, ('III','B3'):0, # III only on B2
}

# Effective machine hours
eff_A = {'A1':6000, 'A2':10000}
eff_B = {'B1':4000, 'B2':7000, 'B3':4000}

# Machine processing fees (cost per hour)
fee_A = {'A1':0.05, 'A2':0.03}
fee_B = {'B1':0.06, 'B2':0.11, 'B3':0.05}

# Raw material cost and selling price
raw_cost = {'I':0.25, 'II':0.35, 'III':0.50}
sell_price = {'I':1.25, 'II':2.00, 'III':2.80}

# Decision variables: amount of product p processed on machine m in step A/B
x = pulp.LpVariable.dicts('xA', [(p,m) for p in products for m in A_machines], lowBound=0, cat='Continuous')
y = pulp.LpVariable.dicts('yB', [(p,m) for p in products for m in B_machines], lowBound=0, cat='Continuous')

# Model
prob = pulp.LpProblem('FactoryProfitMax', pulp.LpMaximize)

# Flow balance: for each product total processed in A equals total processed in B
for p in products:
    prob += (pulp.lpSum(x[(p,m)] for m in A_machines) ==
             pulp.lpSum(y[(p,m)] for m in B_machines)), f'Flow_{p}'

# Machine capacity constraints
for m in A_machines:
    prob += (pulp.lpSum(x[(p,m)] * time_A.get((p,m),0) for p in products) <= eff_A[m]), f'CapA_{m}'
for m in B_machines:
    prob += (pulp.lpSum(y[(p,m)] * time_B.get((p,m),0) for p in products) <= eff_B[m]), f'CapB_{m}'

# Disallow infeasible assignments by setting time to 0 and forcing variable to 0
for p in products:
    for m in A_machines:
        if time_A.get((p,m),0) == 0:
            prob += x[(p,m)] == 0, f'NoA_{p}_{m}'
    for m in B_machines:
        if time_B.get((p,m),0) == 0:
            prob += y[(p,m)] == 0, f'NoB_{p}_{m}'

# Objective: profit = revenue - raw material cost - machine processing fees
revenue = pulp.lpSum((pulp.lpSum(x[(p,m)] for m in A_machines)) * sell_price[p] for p in products)
material = pulp.lpSum((pulp.lpSum(x[(p,m)] for m in A_machines)) * raw_cost[p] for p in products)
costA = pulp.lpSum(x[(p,m)] * time_A[(p,m)] * fee_A[m] for p in products for m in A_machines if time_A.get((p,m),0)>0)
costB = pulp.lpSum(y[(p,m)] * time_B[(p,m)] * fee_B[m] for p in products for m in B_machines if time_B.get((p,m),0)>0)

prob += revenue - material - costA - costB

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

print(f'STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}')
