x_II = pulp.LpVariable('x_II', lowBound=0, cat='Continuous')
x_III = pulp.LpVariable('x_III', lowBound=0, cat='Continuous')

prob = pulp.LpProblem('MaxProfit', pulp.LpMaximize)

# Parameters
price = {'I': 1.25, 'II': 2.00, 'III': 2.80}
raw = {'I': 0.25, 'II': 0.35, 'III': 0.50}
profit_per_unit = {k: price[k] - raw[k] for k in price}

# Equipment data: (available_time, cost_full_load, cost_per_time)
equip = {
    'A1': (6000, 300),
    'A2': (10000, 321),
    'B1': (4000, 250),
    'B2': (7000, 783),
    'B3': (4000, 200)
}
cost_per_time = {e: equip[e][1] / equip[e][0] for e in equip}
avail_time = {e: equip[e][0] for e in equip}

# Processing times (time per unit) – blanks are omitted
time = {
    ('A1','I'):5, ('A1','II'):10,
    ('A2','I'):7, ('A2','II'):9, ('A2','III'):12,
    ('B1','I'):6, ('B1','II'):8,
    ('B2','I'):4, ('B2','III'):11,
    ('B3','I'):7
}

# Equipment capacity constraints
for e in equip:
    expr = pulp.LpAffineExpression()
    for p in ['I','II','III']:
        key = (e, p)
        if key in time:
            coeff = time[key]
            if p == 'I':
                expr += coeff * x_I
            elif p == 'II':
                expr += coeff * x_II
            elif p == 'III':
                expr += coeff * x_III
    prob += (expr <= avail_time[e], f'Cap_{e}')

# Objective: profit from products minus equipment operating cost
revenue = profit_per_unit['I'] * x_I + profit_per_unit['II'] * x_II + profit_per_unit['III'] * x_III

