    for p in ['I','II','III']:
        key = (e, p)
        if key in time:
            coeff = time[key]
            if p == 'I':
                expr += coeff * x_I
            elif p == 'II':
                expr += coeff * x_II
            elif p == 'III':
                expr += coeff * x_III
    equip_cost += cost_per_time[e] * expr

prob += revenue - equip_cost

